create table if not exists properties(id uuid primary key default gen_random_uuid(),user_id uuid default auth.uid(),title text not null,state text not null,district text,locality text,price_inr numeric,area_sqft numeric,area_type text,rera_number text,source_url text,retrieved_at timestamptz default now(),raw jsonb not null,created_at timestamptz default now());create table if not exists verifications(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,kind text not null,status text not null default 'pending',official_url text,evidence jsonb,verified_at timestamptz,created_at timestamptz default now());create table if not exists comparables(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,source_url text,price_inr numeric,area_sqft numeric,area_type text,monthly_rent numeric,retrieved_at timestamptz,notes text);create table if not exists analyses(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,assumptions jsonb not null,metrics jsonb not null,red_flags jsonb not null,created_at timestamptz default now());alter table properties enable row level security;alter table verifications enable row level security;alter table comparables enable row level security;alter table analyses enable row level security;create policy "owners manage properties" on properties for all using(user_id=auth.uid()) with check(user_id=auth.uid());